import re

def parse_dialog(dialog_text, company_id):
    """Parse a dialog into customer messages and agent messages."""
    lines = dialog_text.strip().split('\n\n')
    customer_msgs = []
    agent_msgs = []

    for line in lines:
        if line.startswith(company_id):
            agent_msgs.append(line)
        else:
            customer_msgs.append(line)

    return customer_msgs, agent_msgs

# Check for apology keywords in agent messages
apology_keywords = ['sorry', 'apologize', 'apologies', 'apology', 'regret', 'apologise']

def has_apology(agent_msgs):
    """Check if any agent message contains an apology."""
    text = ' '.join(agent_msgs).lower()
    return any(kw in text for kw in apology_keywords)

